package pf.ska987.patenteasy;
import java.nio.file.*;import org.json.*;
public class TestsCatalogue {
 public static void main(String[] args)throws Exception{Path d=Paths.get(args[0]);JSONObject catalogue=new JSONObject(Files.readString(d.resolve("catalogue.json")));String cle=Files.readString(d.resolve("publique.txt"));JSONObject versions=Catalogue.versions(catalogue,cle);if(!Catalogue.canon(versions).equals(Files.readString(d.resolve("canonique.txt"))))throw new AssertionError("Canonicalisation différente de Python.");if(Catalogue.comparer("0.3.10","0.3.9")<=0)throw new AssertionError("Version lexicographique");if(Catalogue.comparer("0.4.5.1","0.4.5")<=0||Catalogue.comparer("0.4.5.1","0.4.6")>=0||Catalogue.comparer("0.4.5.10","0.4.5.1")<=0||Catalogue.comparer("0.4.5","0.4.5.0")!=0)throw new AssertionError("Version corrective mal comparée");for(String invalide:new String[]{"0.4","0.4.5.1.2","0.4.5-beta","0.4.-5","0.4.5."}){boolean invalideRefuse=false;try{Catalogue.comparer(invalide,"0.4.5");}catch(IllegalArgumentException e){invalideRefuse=true;}if(!invalideRefuse)throw new AssertionError("Version invalide acceptée");}catalogue.getJSONObject("versions").getJSONObject("android").put("taille",1);boolean refus=false;try{Catalogue.versions(catalogue,cle);}catch(Exception e){refus=true;}if(!refus)throw new AssertionError("Signature altérée acceptée");System.out.println("Contrôles du catalogue réussis : Unicode, versions, signature altérée.");}
}
